"""Finalize bounded last-two reports from measured artifacts and explicit lead adjudication."""
import csv,json
from pathlib import Path
import numpy as np
B=Path(__file__).resolve().parent;S=json.loads((B/'SOURCE-SNAPSHOT.json').read_text());G=json.loads((B/'gaia-geometry.json').read_text());A=json.loads((B/'coverage-alias.json').read_text());Q=list(csv.DictReader((B/'queue.csv').open(newline='',encoding='utf-8')));dec=json.loads((B/'lead-decisions.json').read_text());rows=[]
for q in Q:
 tic=q['tic'];p=B/tic/'measurements.json';m=json.loads(p.read_text());d=dec[tic];g=G[tic];ga=S[tic]['target']['gaia'];al=A[tic]['aliases'];good=[e for e in m['events'] if e.get('timing_usable')];dur=float(np.median([e['duration_days'] for e in good]));c=g['closest'];ep=m['reference_epoch_btjd'];P=m['period_days'];er=m['period_error_days']
 m.update(physical_verdict=d['verdict'],full_review_completion='COMPLETE',catalogue_status='UNKNOWN_INCOMPLETE_SCOPED_CHECKS',source_attribution=d['attribution'],independent_reduction=d['reduction'],limitations=d['limitations'],next_check=d['next_check'],epoch_kind=d['epoch_kind'],duration_median_days=dur,geometry_artifact='../gaia-geometry.json',aliases_artifact='../coverage-alias.json',catalogue_artifact='catalogue-evidence.json');p.write_text(json.dumps(m,indent=2)+'\n')
 txt=[f"# {q['review_id']} — TIC {tic}", '',f"**Physical verdict: {d['verdict']}. Bounded review completion: COMPLETE. Catalogue novelty: UNKNOWN / INCOMPLETE SCOPED CHECKS.**",'',f"Locked Gaia DR3 {q['gaia_dr3_source_id']}; RA {ga['ra']}, Dec {ga['dec']} deg; Gaia G {ga['phot_g_mean_mag']}. Exact queue/snapshot/source identity and SHA-256 checks passed. This is one selected period-fold candidate, not a blind-search completeness or occurrence estimate.",'',f"{d['summary']}",'',f"## Raw events and measured clock",'',f"Quality-zero finite positive QLP SAP_FLUX, with local out-of-eclipse normalization and linear-baseline trapezoid fits, gives **P = {P:.10f} ± {er:.10f} d**, reference BTJD **{ep:.8f} ± {m['epoch_error_days']:.8f}**, for **{d['epoch_kind']}**. These are actual fitted event centers, not the screening predictions. Median realized central depth {m['depth_ppt']:.3f} ppt and representative duration {dur:.4f} d ({24*dur:.2f} h) are diluted pipeline measurements.",'',"| Sector | Selected-kind cycle | Measured BTJD | Timing allowance (d) | Realized depth (ppt) | Duration (d) | Adopted |",'|---|---:|---:|---:|---:|---:|---|']
 for e in m['events']:
  if 'mid_btjd' not in e:continue
  txt.append(f"| {e['sector']} | {e['cycle']} | {e['mid_btjd']:.8f} | {e['timing_error_days'] or float('nan'):.7f} | {e['depth_ppt']:.3f} | {e['duration_days']:.4f} | {'yes' if e['timing_usable'] else 'no: '+e.get('timing_exclusion_reason','unusable covariance')} |")
 txt+=['',m['timing_error_meaning']+' Timing allowances are not calibrated coverage intervals. The fit errors exclude model, baseline, dilution and pipeline systematics. `../timing-sensitivity.json` retains leave-one-event-out diagnostics. `raw-events.png` shows the fitted samples; the excluded s26 model, if present, remains visible as rejected evidence.', '',d['kinds'],'','## Recurrence, aliases and actual nulls','',"The selected period predicts no sensitive clean raw null. Near-baseline integer-cycle alternatives N±1 and N±2, plus half, third and double clocks, were tested using actual event centers and actual raw quality/coverage. The double-clock timing test assumes the selected events have the same kind; Gaia's independently measured spectroscopic period also favors the adopted orbital factor. This is a bounded alias check, not a mathematical exclusion of every possible period.",'','| Tested clock | Period (d) | Max selected-kind timing residual (d) | Timing rejected | Sensitive raw nulls |','|---|---:|---:|---|---:|']
 for a in al:txt.append(f"| {a['label']} | {a['period_days']:.8f} | {a['timing_max_residual_days']:.4f} | {a['timing_rejected']} | {a['sensitive_null_count']} |")
 txt+=['',"A sensitive null requires at least 75% central cadence coverage, at least 3 clean central points, at least 4 sideband points on each side, scatter less than one-quarter of the measured event depth, and median deficit + 5×scatter/sqrt(N) below 0.4×event depth; the loss must also be below max(0.1×depth,3×scatter/sqrt(N)). Flagged/incomplete predictions are never clean nulls. The complete per-window counts and deficits are in `../coverage-alias.json`.",'']
 for a in al[1:3]:
  n=a['sensitive_nulls'][0];txt.append(f"Representative {a['label']} null: s{n['sector']} BTJD {n['predicted_btjd']:.6f}, {n['n_core_quality0']} clean core samples, {n['median_deficit_ppt']:.3f} ppt median deficit and {n['scatter_ppt']:.3f} ppt sideband scatter.")
 txt+=['','## Separate extraction and source attribution','',d['reduction'],'',d['attribution'],'',"TESScut aperture extraction is an alternative reduction of the same TESS photons. It tests extraction/processing robustness and does not constitute another observing occasion. Gaia G flux ratios are optimistic capability proxies; no TESS PRF likelihood or calibrated source probability is inferred.",'','## Gaia orbit and physical plausibility','',f"The source-specific {g['solution_type']} solution has P = {g['gaia_period_days']:.10f} ± {g['gaia_period_error_days']:.7f} d, e = {g['eccentricity']:.5f}, omega = {g['omega_deg']:.4f} deg, K1 = {g['semi_amplitude_primary_km_s']:.3f} km/s, and mass function {g['mass_function_solar']:.5f} solar masses. The measured period differs by {g['period_difference_days']:.7f} d ({g['period_difference_days']/g['gaia_period_error_days']:.3f} quoted Gaia sigma). Closest edge-on conjunction {c['kind']} predicts BTJD {c['gaia_conjunction_btjd']:.6f}; measured minus predicted is {c['offset_days']:.6f} d ({c['offset_phase']:.6f} phase), with source-specific linear covariance allowance {c['gaia_linear_covariance_error_days']:.6f} d. The full Gaia correlation matrix is positive definite (minimum eigenvalue {g['covariance_min_eigenvalue']:.6f}).",'',d['geometry'],"The sharp repeated deficits, finite duration and spectroscopic mass function are consistent with stellar eclipses. These checks do not determine component masses, radii or inclination precisely. The orbit comparison uses the published primary velocity and edge-on conjunction approximation. See `gaia-nss-row.json` and `../gaia-geometry.json`.",'','## Catalogue status, limits and next check','',"The shared selected12 catalogue handoff preserves full-source Prsa and IJspeert nonmatches and a successful direct VSX response explicitly empty for this target. VSX API completeness was not independently certified. ASAS-SN and both vetted Kostov scopes remain unavailable; failed requests are unknown. Novelty remains pending, and **no new-system claim follows from this physical review**. Original bulk Gaia/SIMBAD identities and scoped outcomes remain in the sealed shared handoff.",'',d['limitations'],'',f"Next check: {d['next_check']}",'',"Evidence: `measurements.json`, `raw-events.png`, `kind-fold.png`, `catalogue-evidence.json`; shared local analysis files `../coverage-alias.json`, `../gaia-geometry.json`, `../source-verification.json`, `../external-source-verification.json`, and helper artifacts named in the lead audit. No exhaustive all-event fit or Monte Carlo was required. Root alone accepts and integrates the review."]
 (B/tic/'REPORT.md').write_text('\n'.join(txt)+'\n',encoding='utf-8')
 rows.append(dict(review_id=q['review_id'],tic=tic,gaia_dr3_source_id=q['gaia_dr3_source_id'],physical_verdict=d['verdict'],full_review_completion='COMPLETE',catalogue_status='UNKNOWN_INCOMPLETE_SCOPED_CHECKS',period_days=f'{P:.11f}',period_error_days=f'{er:.11f}',reference_epoch_btjd=f'{ep:.8f}',epoch_kind=d['epoch_kind'],depth_ppt=f"{m['depth_ppt']:.3f}",conditional_or_dip_branch_period_days='',limitations=d['limitations'],next_check=d['next_check'],report=str(B/tic/'REPORT.md'),measurements=str(p)))
with (B/'RESULTS.csv').open('w',encoding='utf-8',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
print([(r['tic'],r['physical_verdict']) for r in rows])

